import fs from "node:fs";
import path from "node:path";
import assert from "node:assert/strict";
const files=["docs/reviews/browser-peer-scale-assurance/browser-scale-assurance-preparation.md","docs/reviews/browser-peer-scale-assurance/browser-scale-reader-instructions.md","docs/BOARD.md","docs/VERIFICATION.md"];
const slug=s=>s.trim().toLowerCase().replace(/[`*_~]/gu,"").replace(/[.,:;!?()[\]{}'\''"\\/|<>@#$%^&+=]/gu,"").replace(/\s/gu,"-");
const broken=[];let count=0;
for(const file of files){
 const body=fs.readFileSync(file,"utf8");
 for(const m of body.matchAll(/\]\(([^)\s]*)\)/gu)){
  const ref=m[1];if(/^[a-z][a-z\d+.-]*:/iu.test(ref))continue;
  const [relative,anchor]=ref.split("#");
  const target=relative?path.resolve(path.dirname(file),relative):path.resolve(file);
  count++;
  if(!fs.existsSync(target)){broken.push({file,ref,reason:"missing target"});continue;}
  if(anchor&&target.endsWith(".md")){
   const headings=new Set([...fs.readFileSync(target,"utf8").matchAll(/^#{1,6}\s+(.+?)\s*$/gmu)].map(m=>slug(m[1])));
   if(!headings.has(anchor))broken.push({file,ref,reason:"missing heading"});
  }
 }
}
assert.ok(count>50,"empty or incomplete link population");
assert.deepEqual(broken,[]);
console.log(JSON.stringify({result:"PASS",files,localReferences:count,broken}));
'

